QZ.load("phys", {"chapters":{"1":["1","Making measurements"],"2":["2","Describing motion"],"3":["3","Forces and motion"],"4":["4","Turning effects of forces"],"5":["5","Forces and matter"],"6":["6","Energy stores and transfers"],"7":["7","Energy resources"],"8":["8","Work and power"],"9":["9","The kinetic particle model of matter"],"10":["10","Thermal properties of matter"],"11":["11","Thermal energy transfers"],"12":["12","Sound"],"13":["13","Light"],"14":["14","Properties of waves"],"15":["15","The electromagnetic spectrum"],"16":["16","Magnetism"],"17":["17","Static electricity"],"18":["18","Electrical quantities"],"19":["19","Electric circuits and electrical safety"],"20":["20","Electromagnetic forces"],"21":["21","Electromagnetic induction"],"22":["22","The nuclear atom"],"23":["23","Radioactivity"],"24":["24","Earth and the Solar System"],"25":["25","Stars and the Universe"]},"topics":{"phys-form":["Formulas","Write the formula"],"phys-unit":["Units & values","Recall"],"phys-law":["Laws & rules","State it"],"phys-facts":["Short facts","Answer"]},"cards":[["n-p1-for-density","phys-form",1,"Density","<div class=\"qn-fbox\">ρ = <span class=\"frac\"><span class=\"nu\">m</span><span class=\"de\">V</span></span></div><ul class=\"qn-sym\"><li><b>ρ</b> = density (kg/m³ or g/cm³)</li><li><b>m</b> = mass (kg or g)</li><li><b>V</b> = volume (m³ or cm³)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>m = ρV</b> · <b>V = m ÷ ρ</b></p>",0,""],["n-p1-uni-length-area-and-volume-con","phys-unit",1,"Length, area and volume conversions","<p>1 km = 1000 m; 1 m = 100 cm = 1000 mm; 1 dm = 0.1 m; 1 cm = 0.01 m; 1 mm = 0.001 m; 1 µm = 0.000 001 m (10⁻⁶ m). 1 m² = 10 000 cm². <strong>1 cm³ = 0.000 001 m³ (10⁻⁶ m³)</strong>; <strong>1 dm³ = 0.001 m³ = 1 litre</strong>; <strong>1 cm³ = 1 ml</strong>. Density: <strong>1 g/cm³ = 1000 kg/m³</strong>.</p>",0,""],["n-p1-uni-prefixes-syllabus-section","phys-unit",1,"Prefixes (syllabus Section 4)","<p><strong>M</strong> mega = 10⁶; <strong>k</strong> kilo = 10³; <strong>c</strong> centi = 10⁻²; <strong>m</strong> milli = 10⁻³. <span class=\"qn-ext\">EXT</span> Also <strong>G</strong> giga = 10⁹; <strong>µ</strong> micro = 10⁻⁶; <strong>n</strong> nano = 10⁻⁹.</p>",0,""],["n-p1-fac-an-object-floats-in-a-liqu","phys-facts",1,"When does an object float or sink in a liquid?","<p class=\"qn-lead\">An object <strong>floats</strong> in a liquid if its density is <strong>less</strong> than the liquid's density; it <strong>sinks</strong> if its density is greater.</p>",0,""],["n-p1-fac-one-liquid-floats-on-anoth","phys-facts",1,"When does one liquid float on another?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> One liquid floats on another liquid with a <strong>higher</strong> density, if the two liquids do not mix.</p>",1,""],["n-p2-for-speed","phys-form",2,"Speed","<div class=\"qn-fbox\">v = <span class=\"frac\"><span class=\"nu\">s</span><span class=\"de\">t</span></span></div><ul class=\"qn-sym\"><li><b>v</b> = speed (m/s)</li><li><b>s</b> = distance (m)</li><li><b>t</b> = time (s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>s = vt</b> · <b>t = s ÷ v</b></p>",0,""],["n-p2-for-average-speed","phys-form",2,"Average speed","<div class=\"qn-fbox\">average speed = <span class=\"frac\"><span class=\"nu\">total distance travelled</span><span class=\"de\">total time taken</span></span></div><p class=\"qn-fn\">Use total distance ÷ total time, not the average of the speeds.</p>",0,""],["n-p2-for-acceleration","phys-form",2,"Acceleration","<div class=\"qn-fbox\">a = <span class=\"frac\"><span class=\"nu\">Δv</span><span class=\"de\">Δt</span></span></div><ul class=\"qn-sym\"><li><b>a</b> = acceleration (m/s²)</li><li><b>Δv</b> = change in velocity (m/s)</li><li><b>Δt</b> = time taken (s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>Δv = aΔt</b> · <b>Δt = Δv ÷ a</b></p><p class=\"qn-fn\">Δv = final velocity − initial velocity; it is negative for a deceleration.</p>",1,""],["n-p2-uni-speed-conversions","phys-unit",2,"Speed conversions","<p>km/h → m/s: <strong>÷ 3.6</strong>. m/s → km/h: <strong>× 3.6</strong>. e.g. 72 km/h = 20 m/s.</p>",0,""],["n-p2-fac-speed-gradient-of-a-distan","phys-facts",2,"What does the gradient of a distance–time graph give?","<p class=\"qn-lead\">Speed = gradient of a distance–time graph (straight-line part).</p><div class=\"qn-more\"><p>Gradient = rise ÷ run, using a large triangle.</p></div>",0,""],["n-p2-fac-distance-travelled-area-un","phys-facts",2,"What does the area under a speed–time graph give?","<p class=\"qn-lead\">Distance travelled = area under a speed–time graph.</p><div class=\"qn-more\"><p>Split the area into rectangles and triangles (area of triangle = ½ × base × height).</p></div>",0,""],["n-p2-fac-acceleration-gradient-of-a","phys-facts",2,"What does the gradient of a speed–time graph give?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> Acceleration = gradient of a speed–time graph.</p><div class=\"qn-more\"><p>A negative gradient means deceleration.</p></div>",1,""],["n-p2-fac-the-acceleration-of-free-f","phys-facts",2,"Acceleration of free fall near the Earth&#x27;s surface?","<p class=\"qn-lead\">The acceleration of free fall g for an object near the surface of the Earth is approximately constant and is approximately 9.8 m/s².</p>",0,""],["n-p3-for-weight","phys-form",3,"Weight","<div class=\"qn-fbox\">W = mg</div><ul class=\"qn-sym\"><li><b>W</b> = weight (N)</li><li><b>m</b> = mass (kg)</li><li><b>g</b> = gravitational field strength (N/kg)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>m = W ÷ g</b> · <b>g = W ÷ m</b></p>",0,""],["n-p3-for-force-mass-and-acceleratio","phys-form",3,"Force, mass and acceleration","<div class=\"qn-fbox\">F = ma</div><ul class=\"qn-sym\"><li><b>F</b> = resultant force (N)</li><li><b>m</b> = mass (kg)</li><li><b>a</b> = acceleration (m/s²)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>a = F ÷ m</b> · <b>m = F ÷ a</b></p><p class=\"qn-fn\">The force and the acceleration are in the same direction.</p>",1,""],["n-p3-for-momentum","phys-form",3,"Momentum","<div class=\"qn-fbox\">p = mv</div><ul class=\"qn-sym\"><li><b>p</b> = momentum (kg m/s)</li><li><b>m</b> = mass (kg)</li><li><b>v</b> = velocity (m/s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>v = p ÷ m</b></p>",1,""],["n-p3-for-impulse","phys-form",3,"Impulse","<div class=\"qn-fbox\">impulse = FΔt = Δ(mv)</div><ul class=\"qn-sym\"><li><b>F</b> = force (N)</li><li><b>Δt</b> = time the force acts (s)</li><li><b>Δ(mv)</b> = change in momentum (kg m/s)</li></ul><p class=\"qn-fn\">Unit N s. Change in momentum = mv − mu (final − initial).</p>",1,""],["n-p3-for-resultant-force-from-momen","phys-form",3,"Resultant force from momentum","<div class=\"qn-fbox\">F = <span class=\"frac\"><span class=\"nu\">Δp</span><span class=\"de\">Δt</span></span></div><ul class=\"qn-sym\"><li><b>F</b> = resultant force (N)</li><li><b>Δp</b> = change in momentum (kg m/s)</li><li><b>Δt</b> = time (s)</li></ul>",1,""],["n-p3-uni-acceleration-of-free-fall","phys-unit",3,"Acceleration of free fall","<p><strong>g = 9.8 m/s²</strong> (= 9.8 N/kg) near the Earth's surface.</p>",0,""],["n-p3-law-newton-s-first-law","phys-law",3,"Newton's first law","<p><strong>An object either remains at rest or continues in a straight line at constant speed unless acted on by a resultant force.</strong> A resultant force may change the velocity of an object by changing its <strong>speed</strong> or its <strong>direction</strong> of motion.</p>",0,""],["n-p3-law-conservation-of-momentum","phys-law",3,"Conservation of momentum","<p><strong>When objects collide or explode, the total momentum before equals the total momentum after</strong>, provided no external force acts. Take one direction as positive; velocities in the opposite direction are negative.</p>",1,""],["n-p3-fac-weights-and-masses-can-be","phys-facts",3,"How can weights (and masses) be compared?","<p class=\"qn-lead\">Weights (and masses) can be compared using a balance.</p>",0,""],["n-p3-fac-forces-can-change-the-size","phys-facts",3,"What can forces change about an object?","<p class=\"qn-lead\">Forces can change the size, shape, speed and direction of motion of an object.</p>",0,""],["n-p4-for-moment-of-a-force","phys-form",4,"Moment of a force","<div class=\"qn-fbox\">moment = F × d</div><ul class=\"qn-sym\"><li><b>F</b> = force (N)</li><li><b>d</b> = perpendicular distance from the pivot to the line of the force (m)</li></ul><p class=\"qn-fn\">Unit N m. In equilibrium: sum of clockwise moments = sum of anticlockwise moments.</p>",0,""],["n-p4-law-principle-of-moments","phys-law",4,"Principle of moments","<p><strong>For an object in equilibrium, the sum of the clockwise moments about any point equals the sum of the anticlockwise moments about that point.</strong> <span class=\"qn-ext\">EXT</span> Use it with more than one force on each side of the pivot: add all the clockwise moments and all the anticlockwise moments.</p>",1,""],["n-p4-fac-turning-effect-increases-i","phys-facts",4,"Two ways to increase a turning effect?","<p class=\"qn-lead\">Turning effect increases if the force is bigger or acts further from the pivot.</p>",0,""],["n-p4-fac-the-pivot-force-is-equal-t","phys-facts",4,"Pivot force when a beam is balanced?","<p class=\"qn-lead\">The pivot force is equal to the total downward force when a beam is balanced.</p><div class=\"qn-more\"><p>No resultant force.</p></div>",0,""],["n-p5-for-pressure","phys-form",5,"Pressure","<div class=\"qn-fbox\">p = <span class=\"frac\"><span class=\"nu\">F</span><span class=\"de\">A</span></span></div><ul class=\"qn-sym\"><li><b>p</b> = pressure (Pa)</li><li><b>F</b> = force (N)</li><li><b>A</b> = area (m²)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>F = pA</b> · <b>A = F ÷ p</b></p>",0,""],["n-p5-for-spring-constant","phys-form",5,"Spring constant","<div class=\"qn-fbox\">k = <span class=\"frac\"><span class=\"nu\">F</span><span class=\"de\">x</span></span></div><ul class=\"qn-sym\"><li><b>k</b> = spring constant (N/m)</li><li><b>F</b> = force or load (N)</li><li><b>x</b> = extension (m)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>F = kx</b> · <b>x = F ÷ k</b></p>",1,""],["n-p5-for-change-in-pressure-in-a-li","phys-form",5,"Change in pressure in a liquid","<div class=\"qn-fbox\">Δp = ρgΔh</div><ul class=\"qn-sym\"><li><b>Δp</b> = change in pressure (Pa)</li><li><b>ρ</b> = density of the liquid (kg/m³)</li><li><b>g</b> = 9.8 N/kg</li><li><b>Δh</b> = change in depth (m)</li></ul>",1,""],["n-p5-for-stretched-length","phys-form",5,"Stretched length","<div class=\"qn-fbox\">stretched length = original length + extension</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>extension = stretched length − original length</b></p>",0,""],["n-p5-uni-pressure-units","phys-unit",5,"Pressure units","<p>1 Pa = 1 N/m². 1 N/cm² = 10 000 Pa. 1 kPa = 1000 Pa.</p>",0,""],["n-p5-law-hooke-s-law","phys-law",5,"Hooke's law","<p><strong>The extension of a spring is directly proportional to the load (force) applied, provided the limit of proportionality is not exceeded.</strong> F = kx.</p>",0,""],["n-p5-fac-forces-can-change-the-size","phys-facts",5,"Apart from motion, what can a force change about an object?","<p class=\"qn-lead\">Forces can change the size and shape of an object.</p>",0,""],["n-p5-fac-pressure-in-a-liquid-does","phys-facts",5,"What does pressure in a liquid depend on, and not depend on?","<p class=\"qn-lead\">Pressure in a liquid does not depend on the shape of the container, only on depth and density.</p>",0,""],["n-p6-for-conservation-of-energy-in","phys-form",6,"Conservation of energy in a transfer","<div class=\"qn-fbox\">total energy input = useful energy output + wasted energy</div><p class=\"qn-fn\">e.g. a cyclist going uphill: chemical energy in = kinetic + gravitational potential + thermal energy out.</p>",0,""],["n-p6-for-efficiency-energy","phys-form",6,"Efficiency (energy)","<div class=\"qn-fbox\">efficiency = <span class=\"frac\"><span class=\"nu\">useful energy output</span><span class=\"de\">total energy input</span></span></div><p class=\"qn-fn\">No unit. Always less than 1 (less than 100%).</p>",1,""],["n-p6-for-percentage-efficiency","phys-form",6,"Percentage efficiency","<div class=\"qn-fbox\">% efficiency = <span class=\"frac\"><span class=\"nu\">useful energy output</span><span class=\"de\">total energy input</span></span> × 100%</div>",1,""],["n-p6-for-change-in-gravitational-po","phys-form",6,"Change in gravitational potential energy","<div class=\"qn-fbox\">ΔEₚ = mgΔh</div><ul class=\"qn-sym\"><li><b>ΔEₚ</b> = change in g.p.e. (J)</li><li><b>m</b> = mass (kg)</li><li><b>g</b> = 9.8 N/kg</li><li><b>Δh</b> = change in height (m)</li></ul>",1,""],["n-p6-for-kinetic-energy","phys-form",6,"Kinetic energy","<div class=\"qn-fbox\">Eₖ = ½mv²</div><ul class=\"qn-sym\"><li><b>Eₖ</b> = kinetic energy (J)</li><li><b>m</b> = mass (kg)</li><li><b>v</b> = speed (m/s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>v = √(2Eₖ ÷ m)</b></p>",1,""],["n-p6-law-principle-of-conservation","phys-law",6,"Principle of conservation of energy","<p><strong>Energy cannot be created or destroyed; it can only be transferred from one store to another.</strong> The total energy stays the same. <span class=\"qn-ext\">EXT</span> Apply it to multi-stage examples, e.g. g.p.e. at the top of a slide = k.e. at the bottom + energy wasted heating the slide.</p>",1,""],["n-p6-law-what-g-p-e-and-k-e-depend","phys-law",6,"What g.p.e. and k.e. depend on","<p><strong>G.p.e. depends on weight (mg) and height:</strong> doubling either doubles the g.p.e. <strong>K.e. depends on mass and speed squared:</strong> doubling the speed makes k.e. <strong>4 times</strong> bigger; tripling it makes k.e. <strong>9 times</strong> bigger.</p>",0,""],["n-p6-fac-friction-is-reduced-by-lub","phys-facts",6,"How is friction reduced?","<p class=\"qn-lead\">Friction is reduced by lubrication.</p><div class=\"qn-more\"><p>Less energy is wasted heating moving parts.</p></div>",0,""],["n-p6-fac-wasted-energy-is-mostly-tr","phys-facts",6,"Where does wasted energy mostly go?","<p class=\"qn-lead\">Wasted energy is mostly transferred to the surroundings as thermal energy (heat) and sound.</p><div class=\"qn-more\"><p>It spreads out and cannot easily be used again.</p></div>",0,""],["n-p6-fac-a-percentage-efficiency-gr","phys-facts",6,"Can a percentage efficiency be greater than 100%?","<p class=\"qn-lead\">A percentage efficiency greater than 100% is impossible.</p><div class=\"qn-more\"><p>It would mean energy is being created.</p></div>",0,""],["n-p6-fac-when-an-object-falls-witho","phys-facts",6,"Falling object (no air resistance): how are g.p.e. and k.e. linked?","<p class=\"qn-lead\">When an object falls (without air resistance), the g.p.e. lost = the k.e. gained: mgΔh = ½mv².<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p>So v = √(2gΔh); the mass cancels.</p></div>",1,""],["n-p6-fac-energy-may-be-stored-as-ki","phys-facts",6,"Name the energy stores.","<p class=\"qn-lead\">Energy may be stored as kinetic, gravitational potential, chemical, elastic (strain), nuclear, electrostatic and internal (thermal).</p><div class=\"qn-more\"><p>Energy is measured in joules (J).</p></div>",0,""],["n-p7-law-comparing-energy-resources","phys-law",7,"Comparing energy resources","<p>Judge each resource by <strong>renewability</strong>, <strong>availability</strong>, <strong>reliability</strong>, <strong>scale</strong> (how much power it can supply, e.g. for a large population), <strong>environmental impact</strong> (climate, land, habitats, pollution) and <strong>cost</strong> (start-up and running costs).</p>",0,""],["n-p7-fac-burning-coal-and-oil-produ","phys-facts",7,"Which gas from burning coal and oil causes acid rain?","<p class=\"qn-lead\">Burning coal and oil produces sulfur dioxide (SO₂), which causes acid rain.</p>",0,""],["n-p7-fac-coal-releases-more-co-than","phys-facts",7,"Which fossil fuel releases the most CO₂ for the same energy?","<p class=\"qn-lead\">Coal releases more CO₂ than oil or natural gas for the same energy.</p>",0,""],["n-p7-fac-burning-biofuels-such-as-w","phys-facts",7,"Health problem from burning wood and dung?","<p class=\"qn-lead\">Burning biofuels such as wood and dung gives off smoke, which causes respiratory and health problems.</p>",0,""],["n-p7-fac-resources-that-produce-no","phys-facts",7,"Which energy resources produce no CO₂ while generating?","<p class=\"qn-lead\">Resources that produce no CO₂ while generating: hydroelectric, tidal, wave, wind, geothermal, solar and nuclear.</p><div class=\"qn-more\"><p>Biomass (biofuel) <strong>does</strong> release CO₂ when burned.</p></div>",0,""],["n-p7-fac-light-and-thermal-radiatio","phys-facts",7,"How long does light take to travel from the Sun to the Earth?","<p class=\"qn-lead\">Light and thermal radiation take about 8 minutes to travel from the Sun to the Earth.</p><div class=\"qn-more\"><p>See Ch 24 for the calculation.</p></div>",0,""],["n-p7-fac-radiation-from-the-sun-is","phys-facts",7,"The Sun is the main source of energy for all our energy resources except…?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> Radiation from the Sun is the main source of energy for all our energy resources <strong>except geothermal, nuclear and tidal</strong>.</p><div class=\"qn-more\"><p>Fossil fuels and biofuels came from plants (photosynthesis); wind and waves come from the Sun heating the air; hydroelectric depends on the water cycle.</p></div>",1,""],["n-p7-fac-research-is-being-carried","phys-facts",7,"What research is being done into nuclear fusion?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> Research is being carried out (e.g. tokamak reactors, sometimes called an \"artificial sun\") into using <strong>nuclear fusion</strong> to produce electrical energy on a large scale.</p>",1,""],["n-p8-for-work-done","phys-form",8,"Work done","<div class=\"qn-fbox\">W = Fd = ΔE</div><ul class=\"qn-sym\"><li><b>W</b> = work done (J)</li><li><b>F</b> = force (N)</li><li><b>d</b> = distance moved in the direction of the force (m)</li><li><b>ΔE</b> = energy transferred (J)</li></ul><p class=\"qn-fn\">Lifting an object: W = mgΔh, the gain in g.p.e.</p>",0,""],["n-p8-for-power","phys-form",8,"Power","<div class=\"qn-fbox\">P = <span class=\"frac\"><span class=\"nu\">W</span><span class=\"de\">t</span></span>   and   P = <span class=\"frac\"><span class=\"nu\">ΔE</span><span class=\"de\">t</span></span></div><ul class=\"qn-sym\"><li><b>P</b> = power (W)</li><li><b>W</b> = work done (J)</li><li><b>ΔE</b> = energy transferred (J)</li><li><b>t</b> = time (s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>W = Pt</b> · <b>t = W ÷ P</b></p>",0,""],["n-p8-for-efficiency-power","phys-form",8,"Efficiency (power)","<div class=\"qn-fbox\">% efficiency = <span class=\"frac\"><span class=\"nu\">useful power output</span><span class=\"de\">total power input</span></span> × 100%</div>",1,""],["n-p8-uni-work-energy-and-power-unit","phys-unit",8,"Work, energy and power units","<p><strong>1 J = 1 N m</strong>. 1 kJ = 1000 J; 1 MJ = 1 000 000 J. <strong>1 W = 1 J/s</strong>; <strong>1 kW = 1000 W</strong>; <strong>1 MW = 1 000 000 W</strong>.</p>",0,""],["n-p8-fac-to-calculate-the-energy-tr","phys-facts",8,"Work done against gravity: which distance do you use?","<p class=\"qn-lead\">To calculate the energy transferred by the force of gravity, use the <strong>vertical height</strong> moved.</p><div class=\"qn-more\"><p>e.g. walking up a ramp: work against gravity = mg × vertical height, not × the length of the ramp.</p></div>",0,""],["n-p8-fac-a-more-powerful-machine-do","phys-facts",8,"What does a more powerful machine do?","<p class=\"qn-lead\">A more powerful machine does the same work in less time.</p>",0,""],["n-p9-for-kelvin-and-celsius","phys-form",9,"Kelvin and Celsius","<div class=\"qn-fbox\">T (in K) = θ (in °C) + 273</div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>θ = T − 273</b></p><p class=\"qn-fn\">e.g. 27 °C = 300 K; 0 K = −273 °C.</p>",0,""],["n-p9-for-pressure-and-volume-of-a-g","phys-form",9,"Pressure and volume of a gas","<div class=\"qn-fbox\">pV = constant,   so   p₁V₁ = p₂V₂</div><ul class=\"qn-sym\"><li><b>p</b> = pressure (Pa)</li><li><b>V</b> = volume (m³ or cm³)</li></ul><p class=\"qn-fn\">Only for a fixed mass of gas at constant temperature. Use the same units on both sides.</p>",1,""],["n-p9-uni-pressure-units","phys-unit",9,"Pressure units","<p><strong>1 Pa = 1 N/m²</strong>. Atmospheric pressure ≈ 100 kPa (about 101 kPa).</p>",0,""],["n-p9-law-kinetic-particle-model-tem","phys-law",9,"Kinetic particle model (temperature and particle motion)","<p><strong>As the temperature of a substance rises, its particles gain kinetic energy and move faster.</strong> At absolute zero (0 K = −273 °C) they have the least kinetic energy.</p>",0,""],["n-p9-law-gas-pressure-and-temperatu","phys-law",9,"Gas pressure and temperature (constant volume)","<p><strong>When a fixed mass of gas is heated at constant volume, its pressure increases</strong>, because the particles move faster, so they hit the walls <strong>more often</strong> and <strong>harder</strong> (with more force).</p>",0,""],["n-p9-law-boyle-s-law-volume-and-pre","phys-law",9,"Boyle's law (volume and pressure)","<p><strong>For a fixed mass of gas at constant temperature, pressure is inversely proportional to volume (pV = constant).</strong> If the volume is made smaller, the particles hit the walls <strong>more often</strong> (the same particles in less space), so the pressure increases.</p>",1,""],["n-p9-fac-molecules-in-a-hot-gas-mov","phys-facts",9,"Molecules in a hot gas compared with a cold gas?","<p class=\"qn-lead\">Molecules in a hot gas move faster than in a cold gas.</p>",0,""],["n-p9-fac-internal-energy-is-the-tot","phys-facts",9,"What is internal energy?","<p class=\"qn-lead\">Internal energy is the total kinetic and potential energy of all the particles in an object.</p><div class=\"qn-more\"><p>A rise in temperature increases internal energy.</p></div>",0,""],["n-p9-fac-the-temperature-of-an-obje","phys-facts",9,"What does the temperature of an object measure?","<p class=\"qn-lead\">The temperature of an object is a measure of the average kinetic energy of its particles.</p>",0,""],["n-p9-fac-at-absolute-zero-the-parti","phys-facts",9,"What happens to particles at absolute zero?","<p class=\"qn-lead\">At absolute zero the particles have the least possible kinetic energy, so the substance cannot be cooled any further.</p>",0,""],["n-p9-fac-absolute-zero-is-273-c-0-k","phys-facts",9,"Absolute zero in °C and in K?","<p class=\"qn-lead\">Absolute zero is −273 °C (0 K).</p>",0,""],["n-p10-for-specific-heat-capacity","phys-form",10,"Specific heat capacity","<div class=\"qn-fbox\">c = <span class=\"frac\"><span class=\"nu\">ΔE</span><span class=\"de\">mΔθ</span></span></div><ul class=\"qn-sym\"><li><b>c</b> = specific heat capacity (J/(kg °C))</li><li><b>ΔE</b> = energy supplied (J)</li><li><b>m</b> = mass (kg)</li><li><b>Δθ</b> = temperature rise (°C)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>ΔE = mcΔθ</b> · <b>Δθ = ΔE ÷ (mc)</b></p>",1,""],["n-p10-law-factors-that-speed-up-evap","phys-law",10,"Factors that speed up evaporation","<p><strong>Evaporation is faster at a higher temperature, with a larger surface area, and with air moving over the surface.</strong> Higher temperature: more particles have enough energy to escape. Larger area: more particles are at the surface. Moving air: removes escaped particles before they can return.</p>",1,""],["n-p10-fac-uses-of-a-bimetallic-strip","phys-facts",10,"Uses of a bimetallic strip?","<p class=\"qn-lead\">Uses of a bimetallic strip: thermostats (switching electrical circuits), fire alarms and frost alarms.</p><div class=\"qn-more\"><p>The metal that expands more ends up on the outside of the bend.</p></div>",0,""],["n-p10-fac-expansion-on-heating-gas-l","phys-facts",10,"Order of expansion on heating: solid, liquid, gas?","<p class=\"qn-lead\">Expansion on heating: gas &gt; liquid &gt; solid.</p>",0,""],["n-p10-fac-a-rise-in-the-temperature","phys-facts",10,"What does a rise in temperature do to an object&#x27;s internal energy?","<p class=\"qn-lead\">A rise in the temperature of an object increases its internal energy.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> It increases the <strong>average kinetic energy of all the particles</strong> in the object.</p></div>",1,""],["n-p11-fac-thermal-conductors-from-be","phys-facts",11,"Thermal conductors, from best to worst?","<p class=\"qn-lead\">Thermal conductors, from best to worst: diamond; silver, copper; aluminium, steel; lead; ice, marble, glass; polythene, nylon; rubber, wood; polystyrene; glass wool (a very good insulator).</p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> Many solids conduct better than insulators but less well than metals.</p></div>",1,""],["n-p11-fac-dull-matt-black-surfaces-a","phys-facts",11,"Best absorbers of infrared radiation?","<p class=\"qn-lead\">Dull (matt) black surfaces are the best absorbers of infrared radiation.</p><div class=\"qn-more\"><p>Absorption depends on the <strong>surface</strong> (colour and texture), not on the material being plastic.</p></div>",0,""],["n-p11-fac-dull-matt-black-surfaces-a-2","phys-facts",11,"Best and worst emitters of infrared radiation?","<p class=\"qn-lead\">Dull (matt) black surfaces are also the best emitters; shiny silver surfaces are the worst emitters.</p>",0,""],["n-p11-fac-infrared-radiation-does-no","phys-facts",11,"Does infrared radiation need a medium?","<p class=\"qn-lead\">Infrared radiation does not need a medium.</p><div class=\"qn-more\"><p>So it travels through a vacuum, e.g. from the Sun.</p></div>",0,""],["n-p11-fac-thermal-radiation-transfer","phys-facts",11,"How does thermal radiation transfer energy?","<p class=\"qn-lead\">Thermal radiation transfers energy as electromagnetic waves (infrared).</p>",0,""],["n-p11-fac-cold-objects-also-cause-co","phys-facts",11,"Can cold objects cause convection currents?","<p class=\"qn-lead\">Cold objects also cause convection currents.</p><div class=\"qn-more\"><p>e.g. air cooled by a freezer compartment is denser and sinks.</p></div>",0,""],["n-p11-fac-for-an-object-to-be-at-a-c","phys-facts",11,"Condition for an object to stay at a constant temperature?","<p class=\"qn-lead\">For an object to be at a constant temperature, it must transfer energy away at the same rate that it receives energy.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p>If it receives energy <strong>faster</strong> than it loses it, its temperature <strong>rises</strong>; if more slowly, its temperature <strong>falls</strong>.</p></div>",1,""],["n-p12-for-speed-of-sound","phys-form",12,"Speed of sound","<div class=\"qn-fbox\">speed = <span class=\"frac\"><span class=\"nu\">distance</span><span class=\"de\">time</span></span></div><ul class=\"qn-sym\"><li>speed (m/s)</li><li>distance (m)</li><li>time (s)</li></ul><p class=\"qn-fn\">For an echo the sound goes there and back: distance to the wall (or depth) = speed × time ÷ 2.</p>",0,""],["n-p12-uni-hertz","phys-unit",12,"Hertz","<p><strong>1 Hz = 1 wave per second</strong> (= 1/s). 1 kHz = 1000 Hz.</p>",0,""],["n-p12-fac-larger-amplitude-louder-so","phys-facts",12,"What does a larger amplitude do to a sound?","<p class=\"qn-lead\">Larger amplitude = louder sound.</p>",0,""],["n-p12-fac-higher-frequency-higher-pi","phys-facts",12,"What does a higher frequency do to a sound?","<p class=\"qn-lead\">Higher frequency = higher pitch.</p>",0,""],["n-p12-fac-the-range-of-human-hearing","phys-facts",12,"Range of human hearing?","<p class=\"qn-lead\">The range of human hearing is about 20 Hz to 20 000 Hz (20 kHz).</p>",0,""],["n-p12-fac-sound-travels-about-1-km-i","phys-facts",12,"Speed of sound in air?","<p class=\"qn-lead\">Sound travels about 1 km in 3 s in air: the speed of sound in air is about 330–350 m/s.</p>",0,""],["n-p12-fac-light-travels-at-300-000-0","phys-facts",12,"Speed of light, compared with sound?","<p class=\"qn-lead\">Light travels at 300 000 000 m/s (3.0 × 10⁸ m/s), about a million times faster than sound.</p><div class=\"qn-more\"><p>This is why you see lightning before you hear thunder.</p></div>",0,""],["n-p12-fac-sound-travels-faster-in-so","phys-facts",12,"Speed of sound in solids, liquids and gases: order?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> Sound travels faster in solids than in liquids, and faster in liquids than in gases.</p><div class=\"qn-more\"><p>The particles are closer together.</p></div>",1,""],["n-p13-for-law-of-reflection","phys-form",13,"Law of reflection","<div class=\"qn-fbox\">i = r</div><ul class=\"qn-sym\"><li><b>i</b> = angle of incidence</li><li><b>r</b> = angle of reflection (both measured from the normal)</li></ul><p class=\"qn-fn\">Your item 27 says the same thing in words.</p>",0,""],["n-p13-for-refractive-index-from-angl","phys-form",13,"Refractive index from angles","<div class=\"qn-fbox\">n = <span class=\"frac\"><span class=\"nu\">sin i</span><span class=\"de\">sin r</span></span></div><ul class=\"qn-sym\"><li><b>n</b> = refractive index (no unit)</li><li><b>i</b> = angle of incidence in air</li><li><b>r</b> = angle of refraction in the material</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>sin r = sin i ÷ n</b></p>",1,""],["n-p13-for-refractive-index-from-crit","phys-form",13,"Refractive index from critical angle","<div class=\"qn-fbox\">n = <span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">sin c</span></span></div><ul class=\"qn-sym\"><li><b>c</b> = critical angle</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>sin c = 1 ÷ n</b></p>",1,""],["n-p13-law-law-of-reflection","phys-law",13,"Law of reflection","<p><strong>The angle of incidence is equal to the angle of reflection.</strong> Both angles are measured from the normal. It applies to all mirrors, flat or curved.</p>",0,""],["n-p13-fac-long-sight-is-corrected-by","phys-facts",13,"Long sight is corrected by which lens?","<p class=\"qn-lead\">Long sight is corrected by a converging lens.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p13-fac-short-sight-is-corrected-b","phys-facts",13,"Short sight is corrected by which lens?","<p class=\"qn-lead\">Short sight is corrected by a diverging lens.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p13-fac-a-magnifying-glass-produce","phys-facts",13,"Image formed by a magnifying glass?","<p class=\"qn-lead\">A magnifying glass produces a virtual, upright, enlarged image.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p13-fac-a-diverging-lens-is-thinne","phys-facts",13,"Shape of a diverging lens?","<p class=\"qn-lead\">A diverging lens is thinner in the middle than at the edges.</p>",0,""],["n-p13-fac-a-converging-lens-is-fatte","phys-facts",13,"Shape of a converging lens?","<p class=\"qn-lead\">A converging lens is fatter in the middle than at the edges.</p>",0,""],["n-p13-fac-the-seven-colours-of-the-v","phys-facts",13,"The colours of the visible spectrum, in order of decreasing wavelength?","<p class=\"qn-lead\">The seven colours of the visible spectrum, in order of decreasing wavelength (increasing frequency): red, orange, yellow, green, blue, indigo, violet.</p><div class=\"qn-more\"><p>Red: longest wavelength, lowest frequency. Violet: shortest wavelength, highest frequency.</p></div>",0,""],["n-p14-for-wave-speed","phys-form",14,"Wave speed","<div class=\"qn-fbox\">v = fλ</div><ul class=\"qn-sym\"><li><b>v</b> = wave speed (m/s)</li><li><b>f</b> = frequency (Hz)</li><li><b>λ</b> = wavelength (m)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>f = v ÷ λ</b> · <b>λ = v ÷ f</b></p>",0,""],["n-p14-for-frequency-and-period","phys-form",14,"Frequency and period","<div class=\"qn-fbox\">f = <span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">T</span></span></div><ul class=\"qn-sym\"><li><b>f</b> = frequency (Hz)</li><li><b>T</b> = period, the time for one complete wave (s)</li></ul><p class=\"qn-fn\">Not in the syllabus list, but useful for oscilloscope traces and a.c. graphs.</p>",0,""],["n-p14-uni-hertz","phys-unit",14,"Hertz","<p><strong>1 Hz = 1/s</strong> (one wave per second). See also Ch 12.</p>",0,""],["n-p14-fac-seismic-waves-from-earthqu","phys-facts",14,"P-waves and S-waves: which is faster, and which type of wave is each?","<p class=\"qn-lead\">Seismic waves from earthquakes: P-waves (primary) are faster, longitudinal waves; S-waves (secondary) are slower, transverse waves.</p>",0,""],["n-p14-fac-sound-is-a-longitudinal-wa","phys-facts",14,"Sound: type of wave and frequency range?","<p class=\"qn-lead\">Sound is a longitudinal wave with frequencies from about 20 Hz to 20 000 Hz.</p>",0,""],["n-p14-fac-waves-transfer-energy-with","phys-facts",14,"What do waves transfer, and what do they not transfer?","<p class=\"qn-lead\">Waves transfer energy without transferring matter.</p><div class=\"qn-more\"><p>Wave motion can be seen in vibrations of ropes and springs and in water waves (ripple tank): the medium only vibrates about a fixed position.</p></div>",0,""],["n-p15-fac-communication-systems-use","phys-facts",15,"Which electromagnetic waves are used for communication?","<p class=\"qn-lead\">Communication systems use radio waves, microwaves, infrared and visible light.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p><strong>Satellites:</strong> communication is mainly by <strong>microwaves</strong>; some satellite phones use <strong>low orbit</strong> satellites; others and direct broadcast satellite TV use <strong>geostationary</strong> satellites. <span class=\"qn-ext\">EXT</span> <strong>Mobile phones and wireless internet:</strong> microwaves (penetrate some walls, need only a short aerial). <strong>Bluetooth:</strong> radio waves (pass through walls but are weakened). <strong>Optical fibres:</strong> visible light or infrared, for cable TV and high-speed broadband (glass is transparent to them, and they carry high rates of data).</p></div>",1,""],["n-p15-fac-visible-spectrum-roygbiv-v","phys-facts",15,"Memory aid for the order of the visible spectrum?","<p class=\"qn-lead\">Visible spectrum: ROYGBIV (VIBGYOR backwards).</p><div class=\"qn-more\"><p>Red has the <strong>longest wavelength</strong> and <strong>lowest frequency</strong>; violet the shortest wavelength and highest frequency.</p></div>",0,""],["n-p15-fac-visible-light-has-a-freque","phys-facts",15,"Frequency and wavelength range of visible light?","<p class=\"qn-lead\">Visible light has a frequency of about 10¹⁴–10¹⁵ Hz (wavelength about 400–700 nm).</p><div class=\"qn-more\"><p>You only need the <strong>order</strong> of the regions, not these numbers.</p></div>",0,""],["n-p15-fac-typical-wavelengths-from-l","phys-facts",15,"Typical wavelength of each region of the electromagnetic spectrum?","<p class=\"qn-lead\">Typical wavelengths, from longest to shortest</p><div class=\"qn-more\"><p>Radio: metres to kilometres; microwaves: about 1 cm; infrared: about 0.01 mm; visible: about 0.0005 mm; ultraviolet, X-rays and gamma rays: shorter still (gamma shortest). Not required, but it helps to fix the order.</p></div>",0,""],["n-p15-fac-in-order-of-increasing-fre","phys-facts",15,"Electromagnetic spectrum in order of increasing frequency? What do all EM waves share?","<p class=\"qn-lead\">In order of <strong>increasing frequency</strong> (decreasing wavelength): <strong>radio waves, microwaves, infrared, visible light, ultraviolet, X-rays, gamma rays.</strong> All electromagnetic waves are transverse and travel at the <strong>same speed in a vacuum</strong>.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> This speed is <strong>3.0 × 10⁸ m/s</strong>, approximately the same in air.</p></div>",1,""],["n-p16-fac-the-relative-strength-of-a","phys-facts",16,"How do field lines show the strength of a magnetic field?","<p class=\"qn-lead\"><span class=\"qn-ext\">EXT</span> The relative strength of a magnetic field is shown by the spacing of the field lines: closer lines, stronger field.</p>",1,""],["n-p16-fac-like-poles-repel-unlike-po","phys-facts",16,"Forces between magnetic poles?","<p class=\"qn-lead\">Like poles repel; unlike poles attract.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p><strong>Repulsion</strong> is the only sure test that an object is a magnet. <span class=\"qn-ext\">EXT</span> Magnetic forces are due to <strong>interactions between magnetic fields</strong>.</p></div>",1,""],["n-p17-uni-charge","phys-unit",17,"Charge","<p>Charge is measured in <strong>coulombs (C)</strong>. One electron has a charge of −1.6 × 10⁻¹⁹ C, so 1 C is the charge of about 6 × 10¹⁸ (6 million million million) electrons.</p>",1,""],["n-p17-fac-electrical-conductors-e-g","phys-facts",17,"Conductors and insulators: the difference in terms of electrons?","<p class=\"qn-lead\">Electrical conductors (e.g. metals) have free electrons that can move; insulators (e.g. plastic, rubber, glass) do not.</p><div class=\"qn-more\"><p>See Ch 18, items 52–53.</p></div>",0,""],["n-p17-fac-there-are-positive-and-neg","phys-facts",17,"Forces between charges?","<p class=\"qn-lead\">There are positive and negative charges. Like charges repel; unlike charges attract.</p><div class=\"qn-more\"><p>Positive repels positive, negative repels negative, positive attracts negative.</p></div>",0,""],["n-p17-fac-charging-a-solid-by-fricti","phys-facts",17,"What moves when a solid is charged by friction?","<p class=\"qn-lead\">Charging a solid by friction involves only a transfer of negative charge (electrons).</p><div class=\"qn-more\"><p>The object that <strong>gains electrons</strong> becomes <strong>negative</strong>; the one that <strong>loses electrons</strong> becomes <strong>positive</strong>. Positive charges (protons) do not move.</p></div>",0,""],["n-p18-for-current-and-charge","phys-form",18,"Current and charge","<div class=\"qn-fbox\">I = <span class=\"frac\"><span class=\"nu\">Q</span><span class=\"de\">t</span></span></div><ul class=\"qn-sym\"><li><b>I</b> = current (A)</li><li><b>Q</b> = charge (C)</li><li><b>t</b> = time (s)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>Q = It</b> · <b>t = Q ÷ I</b></p>",1,""],["n-p18-for-e-m-f-and-p-d-from-work-do","phys-form",18,"E.m.f. and p.d. from work done","<div class=\"qn-fbox\">E = <span class=\"frac\"><span class=\"nu\">W</span><span class=\"de\">Q</span></span>   and   V = <span class=\"frac\"><span class=\"nu\">W</span><span class=\"de\">Q</span></span></div><ul class=\"qn-sym\"><li><b>E</b> = e.m.f. (V)</li><li><b>V</b> = p.d. (V)</li><li><b>W</b> = work done or energy transferred (J)</li><li><b>Q</b> = charge (C)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>W = VQ</b> · <b>Q = W ÷ V</b></p><p class=\"qn-fn\">1 V = 1 J/C.</p>",1,""],["n-p18-for-resistance","phys-form",18,"Resistance","<div class=\"qn-fbox\">R = <span class=\"frac\"><span class=\"nu\">V</span><span class=\"de\">I</span></span></div><ul class=\"qn-sym\"><li><b>R</b> = resistance (Ω)</li><li><b>V</b> = p.d. (V)</li><li><b>I</b> = current (A)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>V = IR</b> · <b>I = V ÷ R</b></p>",0,""],["n-p18-for-electrical-power","phys-form",18,"Electrical power","<div class=\"qn-fbox\">P = IV</div><ul class=\"qn-sym\"><li><b>P</b> = power (W)</li><li><b>I</b> = current (A)</li><li><b>V</b> = p.d. (V)</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>I = P ÷ V</b> · <b>V = P ÷ I</b></p>",0,""],["n-p18-for-electrical-energy","phys-form",18,"Electrical energy","<div class=\"qn-fbox\">E = IVt</div><ul class=\"qn-sym\"><li><b>E</b> = energy (J)</li><li><b>I</b> = current (A)</li><li><b>V</b> = p.d. (V)</li><li><b>t</b> = time (s)</li></ul><p class=\"qn-fn\">Also E = Pt. With P in kW and t in hours, E = Pt gives the energy in kW h.</p>",0,""],["n-p18-uni-current-units","phys-unit",18,"Current units","<p>1 mA = 0.001 A (10⁻³ A); 1 µA = 0.000 001 A (10⁻⁶ A). Current is measured in <strong>amperes (amps, A)</strong>; p.d. and e.m.f. in <strong>volts (V)</strong>; resistance in <strong>ohms (Ω)</strong>; charge in <strong>coulombs (C)</strong>; power in <strong>watts (W)</strong>.</p>",0,""],["n-p18-uni-energy-units","phys-unit",18,"Energy units","<p>1 kW h = 1 kW × 1 h = 1000 W × 3600 s = <strong>3 600 000 J</strong>.</p>",0,""],["n-p18-law-conservation-of-energy-in","phys-law",18,"Conservation of energy in a circuit","<p><strong>The energy given to the charges by the cell equals the total energy given by the charges to the components.</strong> So, in a series circuit, the <strong>e.m.f. = the sum of the p.d.s</strong> across the components.</p>",0,""],["n-p18-law-ohm-s-law-current-and-p-d","phys-law",18,"Ohm's law (current and p.d.)","<p><strong>For a metallic conductor at constant temperature, the current is directly proportional to the p.d.</strong> (resistance is constant). This is why the I–V graph for a resistor is a straight line through the origin.</p>",0,""],["n-p18-fac-electrons-flow-from-to-the","phys-facts",18,"Direction of electron flow compared with conventional current?","<p class=\"qn-lead\">Electrons flow from − to +, the opposite way to conventional current.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p18-fac-despite-its-name-e-m-f-is","phys-facts",18,"Unit of e.m.f.? Is it a force?","<p class=\"qn-lead\">Despite its name, e.m.f. is measured in volts; it is not a force.</p>",0,""],["n-p18-fac-voltmeters-are-always-conn","phys-facts",18,"How are voltmeters and ammeters connected?","<p class=\"qn-lead\">Voltmeters are always connected in parallel; ammeters always in series.</p>",0,""],["n-p18-fac-for-the-same-p-d-a-bigger","phys-facts",18,"Same p.d., bigger resistance: what happens to the current?","<p class=\"qn-lead\">For the same p.d., a bigger resistance means a smaller current.</p><div class=\"qn-more\"><p>I = V ÷ R.</p></div>",0,""],["n-p18-fac-a-resistor-works-the-same","phys-facts",18,"Resistor and diode: does the direction matter?","<p class=\"qn-lead\">A resistor works the same either way round, but a diode does not.</p>",0,""],["n-p18-fac-a-longer-wire-has-more-res","phys-facts",18,"Effect of wire length on resistance?","<p class=\"qn-lead\">A longer wire has more resistance.</p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> R ∝ length.</p></div>",1,""],["n-p18-fac-a-wire-with-a-larger-diame","phys-facts",18,"Effect of wire diameter (cross-sectional area) on resistance?","<p class=\"qn-lead\">A wire with a larger diameter (cross-sectional area) has less resistance.</p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> R ∝ 1 ÷ area.</p></div>",1,""],["n-p18-fac-current-is-directly-propor","phys-facts",18,"Current and p.d. when the resistance is constant?","<p class=\"qn-lead\">Current is directly proportional to p.d. when resistance is constant.</p><div class=\"qn-more\"><p>Ohm's law.</p></div>",0,""],["n-p18-fac-electric-circuits-transfer","phys-facts",18,"What do electric circuits transfer, from where and to where?","<p class=\"qn-lead\">Electric circuits transfer energy from a source (a cell or the mains supply) to the circuit components, and then into the surroundings (e.g.</p><div class=\"qn-more\"><p>as light and thermal energy).</p></div>",0,""],["n-p19-for-resistors-in-series","phys-form",19,"Resistors in series","<div class=\"qn-fbox\">R = R₁ + R₂ + R₃ + …</div><ul class=\"qn-sym\"><li><b>R</b> = combined resistance (Ω)</li></ul>",0,""],["n-p19-for-two-resistors-in-parallel","phys-form",19,"Two resistors in parallel","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">R</span></span> = <span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">R₁</span></span> + <span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">R₂</span></span></div><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>For two resistors only: R = (R₁ × R₂) ÷ (R₁ + R₂)</b></p><p class=\"qn-fn\">The combined resistance is less than the smaller resistor.</p>",1,""],["n-p19-for-potential-divider","phys-form",19,"Potential divider","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">R₁</span><span class=\"de\">R₂</span></span> = <span class=\"frac\"><span class=\"nu\">V₁</span><span class=\"de\">V₂</span></span></div><ul class=\"qn-sym\"><li><b>R₁, R₂</b> = the two resistors in series (Ω)</li><li><b>V₁, V₂</b> = the p.d. across each (V)</li></ul>",1,""],["n-p19-for-series-and-parallel-rules","phys-form",19,"Series and parallel rules","<div class=\"qn-fbox\">Series: V = V₁ + V₂ + …   Parallel: I = I₁ + I₂ + …</div><p class=\"qn-fn\">Series: the current is the same everywhere. Parallel: the p.d. is the same across each branch.</p>",1,""],["n-p19-fac-in-parallel-the-p-d-is-the","phys-facts",19,"P.d. across each branch of a parallel circuit?","<p class=\"qn-lead\">In parallel, the p.d. is the same across each branch.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p19-fac-in-series-the-bigger-the-r","phys-facts",19,"In series, which resistor gets the bigger share of the p.d.?","<p class=\"qn-lead\">In series, the bigger the resistance, the bigger its share of the p.d.</p><div class=\"qn-more\"><p>For a constant current, V = IR rises as R rises.</p></div>",0,""],["n-p19-fac-the-current-at-every-point","phys-facts",19,"Current at different points in a series circuit?","<p class=\"qn-lead\">The current at every point in a series circuit is the same.</p><div class=\"qn-more\"><p>The combined resistance is the <strong>sum</strong> of the resistances; cells in series add their e.m.f.s (if they face the same way).</p></div>",0,""],["n-p19-fac-the-current-from-the-sourc","phys-facts",19,"Parallel circuit: source current compared with branch currents? Combined resistance?","<p class=\"qn-lead\">The current from the source is larger than the current in each branch. The combined resistance of two resistors in parallel is less than that of either resistor by itself.</p><div class=\"qn-more\"><p>Adding branches gives the current more paths.</p></div>",0,""],["n-p19-fac-the-sum-of-the-currents-en","phys-facts",19,"Currents entering and leaving a junction?","<p class=\"qn-lead\">The sum of the currents entering a junction equals the sum of the currents leaving it.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p>This is because charge is conserved: it is not created or destroyed at the junction.</p></div>",1,""],["n-p20-law-right-hand-grip-rule","phys-law",20,"Right-hand grip rule","<p><strong>Grip the wire with your right hand with the thumb pointing in the direction of the (conventional) current; your curled fingers show the direction of the magnetic field lines.</strong> For a solenoid: curl the fingers in the direction of the current in the turns; the thumb points to the N pole.</p>",0,""],["n-p20-law-fleming-s-left-hand-rule","phys-law",20,"Fleming's left-hand rule","<p><strong>Hold the thumb, first finger and second finger of the left hand at right angles: First finger = Field (N to S), seCond finger = Current (conventional), thuMb = Motion (force).</strong> It gives the direction of the force on a current-carrying conductor in a magnetic field.</p>",1,""],["n-p20-fac-the-turning-effect-of-a-mo","phys-facts",20,"Three ways to increase the turning effect of a motor?","<p class=\"qn-lead\">The turning effect of a motor is increased by a stronger magnetic field, a larger current and more turns on the coil.</p>",0,""],["n-p20-fac-reversing-the-current-or-t","phys-facts",20,"Effect on the force of reversing the current, the field, or both?","<p class=\"qn-lead\">Reversing the current or the field reverses the force; reversing both leaves it unchanged.</p>",0,""],["n-p20-fac-a-current-carrying-coil-in","phys-facts",20,"What may a current-carrying coil in a magnetic field experience?","<p class=\"qn-lead\">A current-carrying coil in a magnetic field may experience a turning effect.</p><div class=\"qn-more\"><p>The turning effect increases with <strong>more turns</strong> on the coil, a <strong>larger current</strong>, and a <strong>stronger magnetic field</strong>.</p></div>",0,""],["n-p21-for-transformer-equation","phys-form",21,"Transformer equation","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">Vₚ</span><span class=\"de\">Vₛ</span></span> = <span class=\"frac\"><span class=\"nu\">Nₚ</span><span class=\"de\">Nₛ</span></span></div><ul class=\"qn-sym\"><li><b>V</b> = voltage (V)</li><li><b>N</b> = number of turns</li><li><b>p</b> = primary</li><li><b>s</b> = secondary</li></ul><p class=\"qn-re\"><span class=\"qn-lab\">Rearranged</span> <b>Vₛ = Vₚ × Nₛ ÷ Nₚ</b></p>",0,""],["n-p21-for-100-efficient-transformer","phys-form",21,"100% efficient transformer","<div class=\"qn-fbox\">IₚVₚ = IₛVₛ</div><ul class=\"qn-sym\"><li><b>I</b> = current (A)</li><li><b>V</b> = voltage (V)</li></ul><p class=\"qn-fn\">Power in = power out. Stepping the voltage up steps the current down by the same factor.</p>",1,""],["n-p21-for-power-lost-in-cables","phys-form",21,"Power lost in cables","<div class=\"qn-fbox\">P = I²R</div><ul class=\"qn-sym\"><li><b>P</b> = power lost as thermal energy (W)</li><li><b>I</b> = current in the cable (A)</li><li><b>R</b> = resistance of the cable (Ω)</li></ul><p class=\"qn-fn\">Halving the current makes the loss four times smaller.</p>",1,""],["n-p21-law-fleming-s-right-hand-rule","phys-law",21,"Fleming's right-hand rule","<p><strong>Hold the thumb, first finger and second finger of the right hand at right angles: thuMb = Motion of the wire, First finger = Field (N to S), seCond finger = induced Current.</strong> It gives the direction of the induced current in a wire moving across a magnetic field.</p>",1,""],["n-p21-law-direction-of-an-induced-e","phys-law",21,"Direction of an induced e.m.f. (Lenz's law)","<p><strong>The direction of an induced e.m.f. opposes the change causing it.</strong> e.g. pushing the N pole of a magnet into a coil makes that end of the coil a N pole, which repels the magnet. Pulling the magnet out, or using the other pole, <strong>reverses</strong> the e.m.f.</p>",1,""],["n-p21-fac-an-induced-e-m-f-needs-rel","phys-facts",21,"What is needed to induce an e.m.f.?","<p class=\"qn-lead\">An induced e.m.f. needs relative movement (or a changing field): a stationary magnet in a coil induces nothing.</p>",0,""],["n-p21-fac-transformers-only-work-wit","phys-facts",21,"Which type of current do transformers work with?","<p class=\"qn-lead\">Transformers only work with alternating current.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p22-for-number-of-neutrons","phys-form",22,"Number of neutrons","<div class=\"qn-fbox\">number of neutrons = A − Z</div><ul class=\"qn-sym\"><li><b>A</b> = nucleon (mass) number</li><li><b>Z</b> = proton (atomic) number</li></ul><p class=\"qn-fn\">From: nucleon number = proton number + number of neutrons.</p>",0,""],["n-p22-fac-the-nucleus-is-tiny-compar","phys-facts",22,"Size and mass of the nucleus compared with the whole atom?","<p class=\"qn-lead\">The nucleus is tiny compared with the whole atom but contains almost all of its mass.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p22-fac-atoms-form-positive-ions-b","phys-facts",22,"How do atoms form positive and negative ions?","<p class=\"qn-lead\">Atoms form positive ions by losing electrons, or negative ions by gaining electrons.</p>",0,""],["n-p22-fac-the-relative-charge-on-a-n","phys-facts",22,"Relative charge on a nucleus?","<p class=\"qn-lead\">The <strong>relative charge</strong> on a nucleus is equal to its <strong>proton number Z</strong>.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p>The <strong>relative mass</strong> of a nucleus is approximately equal to its <strong>nucleon number A</strong>.</p></div>",1,""],["n-p23-for-corrected-count-rate","phys-form",23,"Corrected count rate","<div class=\"qn-fbox\">corrected count rate = measured count rate − background count rate</div>",1,""],["n-p23-for-fraction-left-after-n-half","phys-form",23,"Fraction left after n half-lives","<div class=\"qn-fbox\">fraction remaining = (½)ⁿ</div><p class=\"qn-fn\">e.g. after 3 half-lives, ⅛ of the nuclei remain. Not in the syllabus list, but it makes half-life questions quicker.</p>",0,""],["n-p23-fac-effects-of-ionising-radiat","phys-facts",23,"Effects of ionising radiation on living things?","<p class=\"qn-lead\">Effects of ionising radiation on living things: cell death, mutations and cancer.</p>",0,""],["n-p23-fac-uses-of-radioisotopes-smok","phys-facts",23,"Uses of radioisotopes, and the radiation each uses?","<p class=\"qn-lead\">Uses of radioisotopes: smoke alarms (α), irradiating food (γ), sterilising equipment (γ), thickness control (β or γ), diagnosis and treatment of cancer (γ).<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p>See \"Choosing an isotope\" above.</p></div>",1,""],["n-p23-fac-alpha-particles-cannot-pen","phys-facts",23,"Can alpha particles penetrate skin?","<p class=\"qn-lead\">Alpha particles cannot penetrate skin.</p><div class=\"qn-more\"><p>They are dangerous only if the source is swallowed or breathed in.</p></div>",0,""],["n-p23-fac-alpha-particles-are-the-mo","phys-facts",23,"Alpha particles: penetrating power and ionising effect?","<p class=\"qn-lead\">Alpha particles are the most easily absorbed (least penetrating) and the most ionising.</p>",0,""],["n-p23-fac-gamma-radiation-is-the-mos","phys-facts",23,"Gamma radiation: penetrating power and ionising effect?","<p class=\"qn-lead\">Gamma radiation is the most penetrating and the least ionising.</p>",0,""],["n-p24-for-average-orbital-speed","phys-form",24,"Average orbital speed","<div class=\"qn-fbox\">v = <span class=\"frac\"><span class=\"nu\">2πr</span><span class=\"de\">T</span></span></div><ul class=\"qn-sym\"><li><b>v</b> = average orbital speed (m/s or km/s)</li><li><b>r</b> = average radius of the orbit (m or km)</li><li><b>T</b> = orbital period (s)</li></ul><p class=\"qn-fn\">Keep units consistent: km with km/s.</p>",1,""],["n-p24-for-time-for-light-to-travel","phys-form",24,"Time for light to travel","<div class=\"qn-fbox\">time = <span class=\"frac\"><span class=\"nu\">distance</span><span class=\"de\">speed of light</span></span></div><ul class=\"qn-sym\"><li><b>speed of light</b> = 3.0 × 10⁸ m/s</li></ul><p class=\"qn-fn\">e.g. Sun to Earth: 1.5 × 10¹¹ m ÷ 3.0 × 10⁸ m/s = 500 s (about 8 minutes).</p>",0,""],["n-p24-fac-order-of-the-planets-from","phys-facts",24,"Order of the planets from the Sun?","<p class=\"qn-lead\">Order of the planets from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.</p><div class=\"qn-more\"><p>Mnemonic: <strong>M</strong>y <strong>V</strong>ery <strong>E</strong>asy <strong>M</strong>ethod <strong>J</strong>ust <strong>S</strong>peeds <strong>U</strong>p <strong>N</strong>aming.</p></div>",0,""],["n-p24-fac-pluto-and-eris-are-dwarf-p","phys-facts",24,"Pluto and Eris are…?","<p class=\"qn-lead\">Pluto and Eris are dwarf planets (minor planets).</p><div class=\"qn-more\"><p>There are only <strong>eight planets</strong>; there are many thousands of minor planets (dwarf planets and asteroids).</p></div>",0,""],["n-p24-fac-phases-of-the-moon-in-orde","phys-facts",24,"Phases of the Moon, in order?","<p class=\"qn-lead\">Phases of the Moon, in order: new moon, waxing crescent, first quarter, waxing gibbous, full moon, waning gibbous, third (last) quarter, waning crescent.</p><div class=\"qn-more\"><p>The names are not required; you must be able to explain why phases happen.</p></div>",0,""],["n-p24-fac-the-gravitational-field-st","phys-facts",24,"What does the gravitational field strength at a planet&#x27;s surface depend on?","<p class=\"qn-lead\">The gravitational field strength <strong>at the surface</strong> of a planet depends on the <strong>mass</strong> of the planet.</p><div class=\"qn-more\"><p>Around a planet, it <strong>decreases as the distance from the planet increases</strong>.</p></div>",0,""],["n-p24-fac-the-force-that-keeps-an-ob","phys-facts",24,"What force keeps an object in orbit around the Sun?","<p class=\"qn-lead\">The force that keeps an object in orbit around the Sun is the gravitational attraction of the Sun.</p><div class=\"qn-more\"><p>The Sun contains <strong>most of the mass</strong> of the Solar System, which is why the planets orbit it.</p></div>",0,""],["n-p25-for-hubble-constant","phys-form",25,"Hubble constant","<div class=\"qn-fbox\">H₀ = <span class=\"frac\"><span class=\"nu\">v</span><span class=\"de\">d</span></span></div><ul class=\"qn-sym\"><li><b>H₀</b> = Hubble constant (s⁻¹)</li><li><b>v</b> = speed at which the galaxy moves away (m/s)</li><li><b>d</b> = distance of the galaxy from Earth (m)</li></ul>",1,""],["n-p25-for-age-of-the-universe","phys-form",25,"Age of the Universe","<div class=\"qn-fbox\"><span class=\"frac\"><span class=\"nu\">d</span><span class=\"de\">v</span></span> = <span class=\"frac\"><span class=\"nu\">1</span><span class=\"de\">H₀</span></span></div><p class=\"qn-fn\">This is an estimate of the age of the Universe (the time since all its matter was at a single point). Your item 51 says the same: age = reciprocal of the Hubble constant.</p>",1,""],["n-p25-uni-astronomical-values","phys-unit",25,"Astronomical values","<p>1 light-year = 9.5 × 10¹⁵ m. Diameter of the Milky Way ≈ 100 000 light-years. H₀ ≈ 2.2 × 10⁻¹⁸ s⁻¹. Speed of light = 3.0 × 10⁸ m/s.</p>",1,""],["n-p25-law-big-bang-theory","phys-law",25,"Big Bang theory","<p><strong>The Universe began from a single point (all its matter together) and has been expanding ever since.</strong> Evidence: redshift of distant galaxies (the Universe is expanding) and <span class=\"qn-ext\">EXT</span> the CMBR.</p>",0,""],["n-p25-law-hubble-s-law","phys-law",25,"Hubble's law","<p><strong>The speed at which a galaxy is moving away from the Earth is proportional to its distance from the Earth (v = H₀d).</strong></p>",1,""],["n-p25-fac-the-current-estimate-for-h","phys-facts",25,"Current estimate of H₀?","<p class=\"qn-lead\">The current estimate for H₀ is 2.2 × 10⁻¹⁸ per second.<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p25-fac-age-of-the-universe-1-h-4","phys-facts",25,"Age of the Universe, in seconds and in years?","<p class=\"qn-lead\">Age of the Universe ≈ 1 ÷ H₀ ≈ 4.5 × 10¹⁷ s ≈ 14 billion years (14.4 × 10⁹ years).<span class=\"qn-ext\">EXT</span></p>",1,""],["n-p25-fac-the-milky-way-is-one-of-ma","phys-facts",25,"The Milky Way: how many stars, and how big?","<p class=\"qn-lead\">The Milky Way is one of many billions of galaxies; it contains many billions of stars and is about 100 000 light-years across.</p>",0,""],["n-p25-fac-the-sun-radiates-most-of-i","phys-facts",25,"In which regions does the Sun radiate most of its energy?","<p class=\"qn-lead\">The Sun radiates most of its energy as infrared, visible light and ultraviolet.</p><div class=\"qn-more\"><p>Gamma rays are made by fusion deep inside, but the Sun does <strong>not</strong> emit much of its energy as gamma rays.</p></div>",0,""],["n-p25-fac-the-sun-is-a-star-of-mediu","phys-facts",25,"The Sun: size and composition?","<p class=\"qn-lead\">The Sun is a star of medium size, consisting mostly of hydrogen and helium.<span class=\"qn-ext\">EXT</span></p><div class=\"qn-more\"><p><span class=\"qn-ext\">EXT</span> Stars are powered by <strong>nuclear reactions</strong> that release energy; in stable stars, <strong>hydrogen nuclei fuse into helium</strong>.</p></div>",1,""],["n-p25-fac-a-galaxy-is-made-up-of-man","phys-facts",25,"What is a galaxy made of?","<p class=\"qn-lead\">A galaxy is made up of many billions of stars.</p><div class=\"qn-more\"><p>The Sun is a star in the galaxy called the <strong>Milky Way</strong>. The other stars in the Milky Way are much further from the Earth than the Sun is.</p></div>",0,""],["n-p25-fac-redshift-in-the-light-from","phys-facts",25,"What does the redshift of distant galaxies show?","<p class=\"qn-lead\">Redshift in the light from distant galaxies is evidence that the Universe is expanding and supports the Big Bang theory.</p><div class=\"qn-more\"><p>The further away a galaxy is, the greater its redshift, so the faster it is moving away.</p></div>",0,""]],"defs":[["d-p1-density",1,"Density","<p>Density is mass per unit volume.</p>","<p>It tells you how tightly packed the mass is. Unit <strong>kg/m³</strong> or <strong>g/cm³</strong>. Water has a density of 1.0 g/cm³ (1000 kg/m³).</p>",0],["d-p2-speed",2,"Speed","<p>Speed is the distance travelled per unit time.</p>","<p>Unit m/s (also km/h, cm/s).</p>",0],["d-p2-velocity",2,"Velocity","<p>Velocity is speed in a given direction.</p>","<p>It is a vector; speed is a scalar.</p>",0],["d-p2-acceleration",2,"Acceleration<span class=\"qn-ext\">EXT</span>","<p>Acceleration is the change in velocity per unit time.</p>","<p>Unit m/s². <span class=\"qn-ext\">EXT</span> A <strong>deceleration</strong> is a <strong>negative acceleration</strong>.</p>",1],["d-p2-scalar-and-vector-quantities",2,"Scalar and vector quantities<span class=\"qn-ext\">EXT</span>","<p>A scalar quantity has magnitude (size) only.</p><p>A vector quantity has magnitude and direction.</p>","<p><strong>Scalars:</strong> distance, speed, time, mass, energy, temperature. <strong>Vectors:</strong> force, weight, velocity, acceleration, momentum, electric field strength, gravitational field strength.</p>",1],["d-p3-mass",3,"Mass","<p>Mass is a measure of the quantity of matter in an object at rest relative to the observer.</p>","<p>Unit kg. Mass does not change from place to place.</p>",0],["d-p3-weight",3,"Weight<span class=\"qn-ext\">EXT</span>","<p>Weight is a gravitational force on an object that has mass.</p>","<p>Unit N. <span class=\"qn-ext\">EXT</span> Weight is <strong>the effect of a gravitational field on a mass</strong>, so it changes if g changes (e.g. on the Moon).</p>",1],["d-p3-gravitational-field-strength",3,"Gravitational field strength","<p>Gravitational field strength is the force per unit mass.</p>","<p>g = W ÷ m. Unit N/kg. It is <strong>equivalent to the acceleration of free fall</strong> (9.8 N/kg = 9.8 m/s² on Earth).</p>",0],["d-p3-momentum",3,"Momentum<span class=\"qn-ext\">EXT</span>","<p>Momentum is mass × velocity.</p>","<p>p = mv. Unit kg m/s. A vector.</p>",1],["d-p3-impulse",3,"Impulse<span class=\"qn-ext\">EXT</span>","<p>Impulse is force × time for which the force acts.</p>","<p>Impulse = FΔt = Δ(mv), the change in momentum. Unit N s.</p>",1],["d-p3-resultant-force",3,"Resultant force<span class=\"qn-ext\">EXT</span>","<p>Resultant force is the change in momentum per unit time.</p>","<p>It is also the single force that has the same effect as all the forces acting on an object. For forces along one line, add those in the same direction and subtract those in opposite directions.</p>",1],["d-p3-friction-and-drag",3,"Friction and drag","<p>Solid friction is the force between two surfaces that may impede motion and produce heating.</p>","<p><strong>Drag</strong> is friction on an object moving through a liquid or a gas (<strong>air resistance</strong>).</p>",0],["d-p4-moment-of-a-force",4,"Moment of a force","<p>The moment of a force is a measure of its turning effect.</p><p>Moment = force × perpendicular distance from the pivot.</p>","<p>Unit <strong>N m</strong>. Everyday examples: pushing a door far from its hinges, a spanner, a see-saw, a wheelbarrow.</p>",0],["d-p4-centre-of-gravity",4,"Centre of gravity","<p>The point through which the whole weight of an object can be considered to act.</p>","<p>For a uniform, symmetrical object it is at the centre. If the object is hung from a point, it settles with its centre of gravity directly below that point.</p>",0],["d-p4-equilibrium",4,"Equilibrium","<p>When there is no resultant force and no resultant moment, an object is in equilibrium.</p>","",0],["d-p5-limit-of-proportionality",5,"Limit of proportionality<span class=\"qn-ext\">EXT</span>","<p>The point on a load–extension graph beyond which the extension is no longer proportional to the load.</p>","<p>Up to this point the graph is a <strong>straight line through the origin</strong>; after it, the line curves. (Elastic limit is not required.)</p>",1],["d-p5-spring-constant",5,"Spring constant<span class=\"qn-ext\">EXT</span>","<p>The spring constant is the force per unit extension.</p>","<p>k = F ÷ x. Unit N/m (or N/cm). A stiffer spring has a larger k.</p>",1],["d-p5-pressure",5,"Pressure","<p>Pressure is the force per unit area.</p>","<p>p = F ÷ A. Unit <strong>Pa</strong> (= N/m²); N/cm² is also used.</p>",0],["d-p6-efficiency",6,"Efficiency<span class=\"qn-ext\">EXT</span>","<p>The fraction (or percentage) of the energy supplied that is usefully transferred.</p>","<p>No device is 100% efficient: some energy is always wasted, usually as thermal energy (heating) and sound.</p>",1],["d-p8-work-done",8,"Work done","<p>Mechanical or electrical work done is equal to the energy transferred.</p><p>Mechanical work done = force × distance moved in the direction of the force.</p>","<p>Unit <strong>joule (J)</strong>. 1 J is the work done when a force of 1 N moves through 1 m.</p>",0],["d-p8-power",8,"Power","<p>Power is the work done per unit time, and also the energy transferred per unit time.</p>","<p>Unit <strong>watt (W)</strong>; 1 W = 1 J/s.</p>",0],["d-p9-absolute-zero",9,"Absolute zero","<p>The lowest possible temperature, −273 °C (0 K), at which the particles have the least kinetic energy.</p>","<p>Nothing can be cooled below it.</p>",0],["d-p10-specific-heat-capacity",10,"Specific heat capacity<span class=\"qn-ext\">EXT</span>","<p>The energy required per unit mass per unit temperature increase.</p>","<p>In other words, the energy needed to raise the temperature of <strong>1 kg</strong> of the substance by <strong>1 °C</strong>. Unit <strong>J/(kg °C)</strong> (or J/(g °C)). Water has a high value (4200 J/(kg °C)), so it heats up and cools down slowly.</p>",1],["d-p11-thermal-radiation",11,"Thermal radiation","<p>Thermal radiation is infrared radiation; all objects emit it.</p>","<p>It is an electromagnetic wave, so it <strong>does not need a medium</strong> and can travel through empty space (a vacuum).</p>",0],["d-p12-frequency",12,"Frequency","<p>The number of waves passing a point (or produced by the source) per second.</p>","<p>Unit <strong>hertz (Hz)</strong>. For sound, a higher frequency means a <strong>higher pitch</strong>.</p>",0],["d-p12-echo",12,"Echo","<p>An echo is the reflection of sound waves.</p>","<p>Hard, flat surfaces reflect sound well.</p>",0],["d-p12-ultrasound",12,"Ultrasound","<p>Sound with a frequency higher than 20 kHz.</p>","<p>Too high for humans to hear.</p>",0],["d-p13-normal-angle-of-incidence-refl",13,"Normal, angle of incidence, reflection and refraction","<p>The normal is a line at 90° to a surface at the point where the ray hits it.</p><p>The angles of incidence, reflection and refraction are measured between the ray and the normal.</p>","",0],["d-p13-refractive-index-n",13,"Refractive index, n<span class=\"qn-ext\">EXT</span>","<p>The ratio of the speeds of a wave in two different regions.</p>","<p>n = speed of light in air (vacuum) ÷ speed of light in the material. It measures how much the material bends (refracts) light. Glass: n ≈ 1.5. No unit.</p>",1],["d-p13-critical-angle",13,"Critical angle","<p>The angle of incidence inside the denser medium for which the angle of refraction is 90°.</p>","<p>If the angle of incidence is <strong>greater</strong> than the critical angle, total internal reflection happens. Glass: c ≈ 42°.</p>",0],["d-p13-monochromatic-light",13,"Monochromatic light<span class=\"qn-ext\">EXT</span>","<p>Visible light of a single frequency is described as monochromatic.</p>","<p>e.g. light from a laser.</p>",1],["d-p13-principal-axis",13,"Principal axis","<p>The line passing through the centre of a lens, perpendicular to its surface.</p>","",0],["d-p13-principal-focus-focal-point",13,"Principal focus (focal point)","<p>The point at which rays of light parallel to the principal axis converge after passing through a converging lens.</p>","",0],["d-p13-focal-length",13,"Focal length","<p>The distance from the centre of the lens to its principal focus.</p>","<p>A fatter (more curved) lens has a shorter focal length.</p>",0],["d-p13-real-and-virtual-images",13,"Real and virtual images","<p>A real image can be formed on a screen; a virtual image cannot.</p><p>A virtual image is formed where diverging rays are extrapolated backwards.</p>","",0],["d-p14-wavelength",14,"Wavelength, λ","<p>The distance between two adjacent crests (or two adjacent troughs) of a wave.</p>","<p>Unit m (or cm, nm).</p>",0],["d-p14-crest-trough-and-amplitude",14,"Crest, trough and amplitude","<p>A crest (peak) is the highest point of a wave; a trough is the lowest point.</p><p>Amplitude is the greatest height or depth of a wave from its undisturbed position.</p>","",0],["d-p14-wave-speed",14,"Wave speed","<p>The distance travelled by a wave per unit time.</p>","<p>It is the speed at which the crests (and the energy) move. Unit m/s.</p>",0],["d-p14-wavefront",14,"Wavefront","<p>A line joining adjacent points on a wave that are all in step with each other.</p>","<p>e.g. the line along each crest in a ripple tank. The wavelength is the distance between neighbouring wavefronts.</p>",0],["d-p14-transverse-wave",14,"Transverse wave","<p>A wave in which the direction of vibration is at right angles to the direction of propagation.</p>","<p>Examples: <strong>electromagnetic radiation</strong>, <strong>water waves</strong>, seismic <strong>S-waves</strong> (secondary).</p>",0],["d-p14-longitudinal-wave",14,"Longitudinal wave","<p>A wave in which the direction of vibration is parallel to the direction of propagation.</p>","<p>Examples: <strong>sound waves</strong>, seismic <strong>P-waves</strong> (primary). They have compressions and rarefactions.</p>",0],["d-p16-magnetic-field",16,"Magnetic field","<p>A region in which a magnetic pole experiences a force.</p>","",0],["d-p16-direction-of-a-magnetic-field",16,"Direction of a magnetic field","<p>The direction of a magnetic field at a point is the direction of the force on the N pole of a magnet at that point.</p>","<p>So field lines go from <strong>N to S</strong> outside a magnet.</p>",0],["d-p17-electric-field",17,"Electric field<span class=\"qn-ext\">EXT</span>","<p>A region in which an electric charge experiences a force.</p>","",1],["d-p17-direction-of-an-electric-field",17,"Direction of an electric field<span class=\"qn-ext\">EXT</span>","<p>The direction of an electric field at a point is the direction of the force on a positive charge at that point.</p>","<p>So field lines point <strong>away from positive</strong> and <strong>towards negative</strong> charges.</p>",1],["d-p18-electric-current",18,"Electric current<span class=\"qn-ext\">EXT</span>","<p>Current is the charge passing a point per unit time.</p>","<p>I = Q ÷ t. Unit <strong>ampere (A)</strong>. Measured with an <strong>ammeter in series</strong>.</p>",1],["d-p18-conventional-current",18,"Conventional current<span class=\"qn-ext\">EXT</span>","<p>Conventional current is from positive to negative; the flow of free electrons is from negative to positive.</p>","",1],["d-p18-electromotive-force-e-m-f",18,"Electromotive force (e.m.f.)","<p>The electrical work done by a source in moving a unit charge around a complete circuit.</p>","<p>Measured in <strong>volts (V)</strong>. It is the energy the source gives to each coulomb.</p>",0],["d-p18-potential-difference-p-d",18,"Potential difference (p.d.)","<p>The work done by a unit charge passing through a component.</p>","<p>Measured in <strong>volts (V)</strong> with a <strong>voltmeter in parallel</strong>. It is the energy each coulomb transfers to the component.</p>",0],["d-p18-kilowatt-hour-kw-h",18,"Kilowatt-hour (kW h)","<p>The energy transferred by a 1 kW appliance in 1 hour.</p>","<p>1 kW h = 3 600 000 J (3.6 MJ). <strong>Cost = number of kW h × price per kW h.</strong></p>",0],["d-p22-proton-number-atomic-number-z",22,"Proton number (atomic number), Z","<p>The number of protons in the nucleus.</p>","<p>It decides which element the atom is.</p>",0],["d-p22-nucleon-number-mass-number-a",22,"Nucleon number (mass number), A","<p>The number of protons plus neutrons (nucleons) in the nucleus.</p>","",0],["d-p22-isotopes",22,"Isotopes","<p>Atoms of the same element with the same number of protons but different numbers of neutrons.</p>","<p>(Same Z, different A.) An element may have more than one isotope, e.g. carbon-12 and carbon-14.</p>",0],["d-p23-background-radiation",23,"Background radiation","<p>The radiation from the environment to which we are exposed all the time.</p>","<p>Main sources: <strong>radon gas</strong> (in the air), <strong>rocks and buildings</strong>, <strong>food and drink</strong>, and <strong>cosmic rays</strong>.</p>",0],["d-p23-radioactive-decay",23,"Radioactive decay","<p>A change in an unstable nucleus that can result in the emission of α-particles or β-particles and/or γ-radiation.</p>","<p>The changes are <strong>spontaneous and random</strong>. During α-decay or β-decay, the nucleus changes to that of a <strong>different element</strong>.</p>",0],["d-p23-half-life",23,"Half-life","<p>The half-life of a particular isotope is the time taken for half the nuclei of that isotope in any sample to decay.</p>","<p>After each half-life, the count rate (and the number of undecayed nuclei) halves. Half-lives range from fractions of a second to billions of years.</p>",0],["d-p24-average-orbital-speed",24,"Average orbital speed<span class=\"qn-ext\">EXT</span>","<p>Average orbital speed v = 2πr ÷ T, where r is the average radius of the orbit and T is the orbital period.</p>","<p>It is the distance round the orbit divided by the time for one orbit.</p>",1],["d-p25-light-year",25,"Light-year<span class=\"qn-ext\">EXT</span>","<p>The distance travelled in (the vacuum of) space by light in one year.</p>","<p><span class=\"qn-ext\">EXT</span> <strong>1 light-year = 9.5 × 10¹⁵ m.</strong> It is a unit of <strong>distance</strong>, not time.</p>",1],["d-p25-redshift",25,"Redshift","<p>An increase in the observed wavelength of electromagnetic radiation emitted from receding stars and galaxies.</p>","<p>The light from distant galaxies appears <strong>redshifted</strong> compared with light emitted on Earth: the spectral lines move towards the <strong>red</strong> (longer wavelength) end. (It is like the drop in pitch of an ambulance siren moving away, the Doppler effect.)</p>",0],["d-p25-hubble-constant-h",25,"Hubble constant, H₀<span class=\"qn-ext\">EXT</span>","<p>The ratio of the speed at which a galaxy is moving away from the Earth to its distance from the Earth.</p>","<p>H₀ = v ÷ d. Unit <strong>s⁻¹</strong> (per second).</p>",1]]});
